# Stable per-command and per-transaction requirements (no command hidden in a group title).
COMMANDS='create_or_load_chat_session list_chat_sessions send_chat_message cancel_chat_turn get_draft_workspace_state get_progress_detail apply_manual_draft_edit confirm_phase regenerate_draft_phase list_draft_versions restore_draft_version list_pending_patches confirm_pending_patch reject_pending_patch confirm_all_pending_patches start_or_resume_workflow cancel_workflow get_workflow_status get_commit_confirmation_preview commit_draft reopen_committed_draft list_projects get_project_detail delete_project list_characters get_character_detail create_or_update_library_character link_library_character_to_draft get_chapter_writing_state set_scene_lock set_chapter_scenes_lock_bulk start_scene_generation cancel_scene_generation respond_edit_scope_expansion list_scene_versions save_chapter get_chapter_save_receipt get_runtime_and_provider_config update_runtime_and_provider_config set_provider_api_key'.split()
assert len(COMMANDS)==40
CMD_OWNER={**{i:'phase3_sprint7_deep4' for i in [1,2,3,4,9]},**{i:'phase3_sprint2_deep0' for i in [5,6,7,8,10,11]},**{i:'phase3_sprint6_deep3' for i in range(12,16)},**{i:'phase4_sprint1_deep0' for i in range(16,19)},**{i:'phase4_sprint2_deep0' for i in range(19,22)},**{i:'phase4_sprint3_deep1' for i in range(22,29)},**{i:'phase4_sprint4_deep1' for i in [29,30,31,35,36,37]},**{i:'phase4_sprint5_deep2' for i in [32,33,34]},**{i:'phase2_sprint4_deep3' for i in [38,39,40]}}
assert len(CMD_OWNER)==40
for n,name in enumerate(COMMANDS,1):
    owner=CMD_OWNER[n]; rid=f'REQ-CMD-{n:03d}'
    R.append((rid,B,f'{2117+n}-{2117+n}',f'MUST implement typed IPC #{n} `{name}` with the specified authorization, DTO, transaction and error behavior.',owner,'ASSIGNED'))
    next(x for x in S if x['id']==owner)['reqs'].append(rid)
TX_OWNER={1:'phase3_sprint2_deep0',2:'phase3_sprint6_deep3',3:'phase3_sprint2_deep0',4:'phase3_sprint10_deep4',5:'phase4_sprint2_deep0',6:'phase4_sprint4_deep1',7:'phase4_sprint4_deep1',8:'phase3_sprint6_deep3'}
for n,owner in TX_OWNER.items():
    rid=f'REQ-TX-{n:03d}'; R.append((rid,B,f'{498+n}-{498+n}',f'MUST own TX-{n:02d} in one BEGIN IMMEDIATE boundary, with documented rollback and independent effects.',owner,'ASSIGNED'))
    next(x for x in S if x['id']==owner)['reqs'].append(rid)
EXTRA=[('REQ-CONTRACT-001',A,'70-83','Resolve listed cross-SSOT contradictions only through owner authority, never coding-agent invention.','phase1_sprint1_deep0','CONTRACT_VALIDATION_REQUIRED'),('REQ-CONTRACT-002',B,'2621-2628','Verify absent historical migration baseline and authorize version path before SQL.','phase1_sprint2_deep1','CONTRACT_VALIDATION_REQUIRED'),('REQ-CONTRACT-003',B,'1549-1549','Verify actual Phase3 consumer projection and artifact budget before freezing codec.','phase1_sprint3_deep0','CONTRACT_VALIDATION_REQUIRED'),('REQ-TOOLS-003',T,'40-50','Read tools and catalog searches MUST use registry caller gate and no Draft Version.','phase3_sprint4_deep1','ASSIGNED'),('REQ-TOOLS-004',B,'781-837','Tool executor MUST enforce declared_sources/declared_source and protect user/user_edited fields per field atomically.','phase3_sprint5_deep2','ASSIGNED'),('REQ-WRITE-004',F,'294-440','Scene version restore UI requires an authoritative backend path; no 41st IPC may be invented.','phase5_sprint5_deep3','CONTRACT_VALIDATION_REQUIRED')]
for r in EXTRA:
    R.append(r); next(x for x in S if x['id']==r[4])['reqs'].append(r[0])
# The 66 named BE test-matrix vectors are individually assigned to an acceptance owner.
TEST_OWNER={'T-UNIT-01':'phase3_sprint1_deep0','T-UNIT-02':'phase2_sprint2_deep1','T-UNIT-03':'phase3_sprint1_deep0','T-UNIT-04':'phase3_sprint1_deep0','T-UNIT-05':'phase2_sprint2_deep1','T-DB-01':'phase2_sprint3_deep1','T-ROLL-01':'phase4_sprint2_deep0','T-CONC-01':'phase3_sprint2_deep0','T-IDEM-01':'phase3_sprint2_deep0','T-REST-01':'phase3_sprint2_deep0','T-PROV-01':'phase3_sprint6_deep3','T-CASC-01':'phase3_sprint5_deep2','T-WF-01':'phase3_sprint10_deep4','T-LOCK-01':'phase4_sprint5_deep2','T-SAVE-01':'phase4_sprint4_deep1','T-REC-01':'phase6_sprint2_deep0','T-IPC-01':'phase2_sprint4_deep3',**{f'MIG-{n:02d}':'phase2_sprint3_deep1' for n in range(1,6)},**{f'WF-{n:02d}':'phase3_sprint10_deep4' for n in range(1,11)},**{f'WF-C{n:02d}':'phase3_sprint10_deep4' for n in range(1,16)},**{f'REC-{n:02d}':'phase3_sprint9_deep2' for n in range(1,16)},'IPC-01':'phase6_sprint2_deep0','IPC-02':'phase6_sprint2_deep0','DB-P01':'phase2_sprint3_deep1','DB-P02':'phase2_sprint3_deep1'}
assert len(TEST_OWNER)==66
be_lines=(Path(__file__).resolve().parent.parent.parent/'docs/business/be-core.md').read_text(encoding='utf-8').splitlines()
for test_id,owner in TEST_OWNER.items():
    matches=[(n+1,t) for n,t in enumerate(be_lines) if t.startswith('| **`'+test_id+'`** |') or t.startswith('| **'+test_id+'** |') or t.startswith('| '+test_id+' |')]
    assert len(matches)==1,(test_id,len(matches))
    line,text=matches[0];rid='REQ-SPECTEST-'+test_id
    R.append((rid,B,f'{line}-{line}',f'MUST implement executable BE acceptance vector {test_id}, preserving scenario and expected result; old v1-only recovery claims remain legacy-only under B+.',owner,'ASSIGNED'))
    next(s for s in S if s['id']==owner)['reqs'].append(rid)
# Per-issue contract ledger. P1S1 may be inventory-accepted, but affected descendants stay blocked.
CONTRACT_ISSUES=[
('CI-01','Migration baseline 0001/0002 absent; version path unapproved',['phase1_sprint2_deep1','phase2_sprint3_deep1']),
('CI-02','Phase-3 merger/consumer exact projection unproven',['phase1_sprint3_deep0','phase3_sprint3_deep0','phase3_sprint9_deep2','phase3_sprint10_deep4','phase4_sprint1_deep0']),
('CI-03','seal_pending_retry/TX01 pending expiry/restore idempotency/nullable phase',['phase3_sprint2_deep0']),
('CI-04','ErrorCode variants incomplete for IPC/error contracts',['phase2_sprint4_deep3','phase2_sprint5_deep2']),
('CI-05','TX-05 table count/insert order differs from Core',['phase4_sprint2_deep0']),
('CI-06','TX-06 cancel-before-persist failure ordering',['phase4_sprint4_deep1']),
('CI-07','themes.resolution_type default OPEN not in enum',['phase2_sprint3_deep1']),
('CI-08','No authoritative scene-version restore IPC',['phase5_sprint5_deep3']),
('CI-09','system_language request-vs-settings precedence',['phase5_sprint2_deep1']),
('CI-10','Provider config persistence semantics missing',['phase2_sprint4_deep3','phase5_sprint6_deep1']),
('CI-11','B+ target represented as unconditional vs spec-only authority',['phase2_sprint3_deep1','phase3_sprint9_deep2']),
]
for issue,desc,affected in CONTRACT_ISSUES:
    for sid in affected:
        s=next(x for x in S if x['id']==sid)
        s['blocked'].append(issue)
for s in S:
    # Every requirement with CONTRACT_VALIDATION_REQUIRED must expose a blocker, even without a manual issue.
    s['blocked']+= [f'CONTRACT_REVIEW_REQUIRED:{rid}' for rid in s['reqs'] if next(r for r in R if r[0]==rid)[5]=='CONTRACT_VALIDATION_REQUIRED']
    s['blocked']=list(dict.fromkeys(s['blocked']))
# One bootstrap owner creates compilation-safe empty module files and registers them once.
# Successor agents replace only their assigned stub files; no parallel mod.rs edits.
BOOT=next(x for x in S if x['id']=='phase2_sprint1_deep0')
BOOT['paths']+=['src-tauri/build.rs','src-tauri/.gitignore','src-tauri/icons/*']
BOOT['contract'].append('Bootstrap must NOT create downstream implementation files or predeclare their modules. Each implementation sprint owns new .rs files and compiles them in its own integration test with `#[path = "..."] mod`; P6S2 alone adds production module declarations/registrations after acceptance. This avoids shared mod.rs writes and placeholder ownership.')
